// ─────────────────────────────────────────────────────────────
// Sound effects via audioplayers. WAV assets live in
// assets/sounds and are generated by tool/generate_sounds.py.
// ─────────────────────────────────────────────────────────────

import 'package:audioplayers/audioplayers.dart';

class SoundService {
  SoundService() {
    for (int i = 0; i < 5; i++) {
      _pool.add(AudioPlayer());
    }
  }

  final List<AudioPlayer> _pool = <AudioPlayer>[];
  int _cursor = 0;
  bool muted = false;

  Future<void> _play(String file) async {
    if (muted) return;
    final AudioPlayer player = _pool[_cursor];
    _cursor = (_cursor + 1) % _pool.length;
    await player.stop();
    await player.play(AssetSource('sounds/$file'));
  }

  void select() => _play('select.wav');
  void move() => _play('move.wav');
  void error() => _play('error.wav');
  void hint() => _play('hint.wav');
  void win() => _play('win.wav');

  Future<void> dispose() async {
    for (final AudioPlayer p in _pool) {
      await p.dispose();
    }
    _pool.clear();
  }
}
